return items.map(item => {
    const args = item.json.arguments;  // Assuming the arguments are stored here
    let formulaParts = [];

    // Loop over each argument to create part of the formula
    for (const key in args) {
        const value = args[key];
        if (typeof value === 'number' || typeof value === 'boolean') {
            formulaParts.push(`{${key}} = ${value}`);
        } else {
            formulaParts.push(`{${key}} = '${value.replace(/'/g, "\\'")}'`); // Escape single quotes in values
        }
    }

    // Combine all parts with AND
    const formula = formulaParts.length > 0 ? `AND(${formulaParts.join(', ')})` : "";
    return { json: { formula } };
});

